import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as a,X as t}from"./chunks/vendor-vueuse.XPft87tp.js";const h=JSON.parse('{"title":"Redis 持久化","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/redis-persistence.md","filePath":"mysql/redis-persistence.md","lastUpdated":1788511308000}'),i={name:"mysql/redis-persistence.md"};function d(o,e,n,p,c,l){return a(),s("div",null,e[0]||(e[0]=[t('<h1 id="redis-持久化" tabindex="-1">Redis 持久化 <a class="header-anchor" href="#redis-持久化" aria-label="Permalink to &quot;Redis 持久化&quot;">​</a></h1><h3 id="redis-的持久化机制有什么-各自的优缺点" tabindex="-1">Redis 的持久化机制有什么，各自的优缺点 <a class="header-anchor" href="#redis-的持久化机制有什么-各自的优缺点" aria-label="Permalink to &quot;Redis 的持久化机制有什么，各自的优缺点&quot;">​</a></h3><p>Redis 主要有 RDB、AOF 和混合持久化。</p><p><strong>RDB</strong> 是快照持久化，把某个时间点的数据生成 dump 文件。优点是文件紧凑、恢复快、适合备份；缺点是两次快照之间宕机可能丢数据，<code>bgsave</code> 时 fork 大进程也可能带来瞬时阻塞。</p><p><strong>AOF</strong> 是追加日志，记录每次写命令。优点是数据丢失更少，<code>appendfsync everysec</code> 通常最多丢 1 秒左右数据；缺点是文件更大，恢复时要重放命令，速度可能慢于 RDB，需要 AOF rewrite 压缩日志。</p><p><strong>混合持久化</strong> 是 AOF rewrite 后文件前半部分用 RDB 格式，后半部分追加增量 AOF，兼顾恢复速度和数据完整性。</p><p>生产里常见选择是开启 AOF everysec，重要数据再配合 RDB 备份。Redis 仍然不适合作为唯一强一致存储。</p><h3 id="恢复时哪个更快" tabindex="-1">恢复时哪个更快 <a class="header-anchor" href="#恢复时哪个更快" aria-label="Permalink to &quot;恢复时哪个更快&quot;">​</a></h3><p>通常 RDB 恢复更快，因为它直接加载快照文件。AOF 要逐条重放写命令，文件越大恢复越慢。</p><p>如果开启混合持久化，恢复速度会接近 RDB，同时保留 AOF 较小的数据丢失窗口。Redis 启动时如果同时存在 RDB 和 AOF，一般优先加载 AOF，因为 AOF 通常数据更新。</p>',10)]))}const R=r(i,[["render",d]]);export{h as __pageData,R as default};
